let ac = null;
async function search(q) {
  ac?.abort();                     // 이전 요청을 끊는다
  ac = new AbortController();
  try {
    const res = await fetch(`/s?q=${q}`, { signal: ac.signal });
    render(await res.json());
  } catch (e) {
    if (e.name !== 'AbortError') throw e;   // 취소는 오류가 아니다
  }
}

async function retry(fn, tries = 4) {
  for (let i = 0; ; i++) {
    try { return await fn(); }
    catch (e) {
      if (i >= tries - 1 || !isRetriable(e)) throw e;    // 400 은 다시 해도 400
      const base = 2 ** i * 200;
      await sleep(base * (0.5 + Math.random()));          // 흔들기
    }
  }
}

// 멱등 키. 서버가 같은 요청을 한 번만 처리하게
fetch('/orders', { method: 'POST', headers: { 'Idempotency-Key': uuid } });

// 작은 배열을 워커 넷에 나누면 오히려 느리다
//   직렬화 + 전송 + 역직렬화 + 결과 합치기 > 계산 시간

// 기준: 한 조각이 최소 수 ms 이상 걸릴 만큼 커야 한다
const CHUNK = 50000;
if (rows.length < CHUNK) return computeInline(rows);

// 지연을 무작위로 끼워 넣어 순서를 흔든다
const chaos = () => new Promise((r) => setTimeout(r, Math.random() * 5));

test('두 번 눌러도 한 번만 저장된다', async () => {
  const p1 = save(); await chaos();
  const p2 = save();
  await Promise.all([p1, p2]);
  expect(await countRows()).toBe(1);   // 멱등한가
});

